#[test]
fn all_eight_original_records_match_the_complete_finite_policy() {
    let rows = captured();
    assert_eq!(rows.len(), 8);
    for (sha, bytes, sm, m) in rows {
        m.validate().unwrap();
        require_record(sha, bytes, sm, &m).unwrap();
    }
}
#[test]
fn every_original_record_refuses_mutated_code_geometry_scalar_pointer_and_access() {
    for (sha, bytes, sm, m) in captured() {
        for kind in 0..10 {
            let mut x = m.clone();
            match kind {
                0 => x.entry.push('x'),
                1 => x.grid[0] += 1,
                2 => x.block[0] += 1,
                3 => x.dynamic_shared_bytes += 16,
                4 => x.parameters[0].template[0] ^= 1,
                5 => x.parameters[0].offset += 8,
                6 => x.bindings[0].bytes += 2,
                7 => x.bindings[0].io = CubinIo::ReadWrite,
                8 => x.fixups[0].binding_offset += 16,
                _ => x.fixups[0].extent += 2,
            }
            assert!(require_record(sha, bytes, sm, &x).is_err(), "field{kind}");
        }
        let mut wrong = sha;
        wrong[0] ^= 1;
        assert!(require_record(wrong, bytes, sm, &m).is_err());
        assert!(require_record(sha, bytes + 1, sm, &m).is_err());
        assert!(require_record(sha, bytes, sm + 1, &m).is_err());
    }
}
#[test]
fn finite_union_has_exact_capacity_and_preserves_existing_scopes() {
    let p = super::super::policy::CubinSetPolicy::FixedPromptMlp;
    assert!(p.limits(5, 7, 7, false, false).is_ok());
    for (modules, functions, records, new_module, new_function) in [
        (5, 7, 7, true, false),
        (5, 7, 7, false, true),
        (5, 7, 8, false, false),
    ] {
        assert!(
            p.limits(modules, functions, records, new_module, new_function)
                .is_err()
        );
    }
    assert!(
        super::super::policy::CubinSetPolicy::ConnectedQwen08
            .limits(7, 12, 20, false, false)
            .is_ok()
    );
    assert!(
        super::super::policy::CubinSetPolicy::ProjectionSix
            .limits(6, 8, 18, false, false)
            .is_ok()
    );
}
